### OnWorkerEvent

Source: https://github.com/nestjs/bull/blob/master/_autodocs/api-reference/bullmq-decorators.md

Registers a worker-event listener. The containing class must be annotated with `@Processor`.

```APIDOC
## `OnWorkerEvent`

### Description
Registers a worker-event listener. The containing class **must** be annotated with `@Processor`.

### Method
Decorator

### Parameters
- `eventName` (`keyof WorkerListener`) - Required - BullMQ `WorkerListener` event name (`'active'`, `'completed'`, `'failed'`, `'error'`, `'progress'`, `'stalled'`, `'closing'`, `'closed'`, `'drained'`, `'paused'`, `'resumed'`, …)

### Usage Example
```ts
import { Processor, WorkerHost, OnWorkerEvent } from '@nestjs/bullmq';
import { Job } from 'bullmq';

@Processor('audio')
export class AudioConsumer extends WorkerHost {
  async process(job: Job): Promise<any> {
    return transcode(job.data);
  }

  @OnWorkerEvent('error')
  onWorkerError(err: Error) {
    console.error('worker error', err);
  }

  @OnWorkerEvent('drained')
  onDrained() {
    console.log('queue drained');
  }
}
```
